[Fact]
public async Task StartBackgroundInspections_SetsSandboxInfoLoadingSynchronously()
{
    var viewModel = new MainWindowViewModel();
    viewModel.StartBackgroundInspections();

    // LoadSandboxPathsAsync sets IsSandboxInfoLoading=true before its
    // first await. When nono is on PATH the subprocess call yields and
    // the flag stays true; when nono is absent the entire inspection
    // completes synchronously. Poll to let any async inspection settle.
    for (var i = 0; i < 100; i++)
    {
        if (!viewModel.IsSandboxInfoLoading)
            break;
        await Task.Delay(2); // vr-allow-sleep: polling for fire-and-forget sandbox inspection completion
    }

    Assert.False(viewModel.IsSandboxInfoLoading);
}

