public async Task StartBackgroundInspections_TriggersBackendStatusRefresh()
{
    var viewModel = new MainWindowViewModel();
    viewModel.StartBackgroundInspections();

    // The probe is fire-and-forget (HTTP GET with 2s timeout). When no
    // backend is listening (the test environment) the probe sets
    // BackendStatusMessage to the not-ready diagnostic. Poll for the
    // message to appear — IsBackendReachable defaults to true so it
    // cannot serve as a probe-has-run signal.
    for (var i = 0; i < 500; i++)
    {
        if (viewModel.BackendStatusMessage is not null)
            break;
        await Task.Delay(10); // vr-allow-sleep: fire-and-forget async probe has no exposed completion signal
    }

    Assert.NotNull(viewModel.BackendStatusMessage);
}

